package net.zartra.gui;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import java.io.*;import java.util.*;
final class MenuManager {private final MenuStorage store;private Map<String,MenuDefinition> menus;private ActionExecutor actions;private ZartraGUIPlugin plugin;private final Map<UUID,Set<String>> viewers=new HashMap<UUID,Set<String>>();private MenuRefreshManager refresh;private final Set<UUID> refreshing=new HashSet<UUID>();MenuManager(MenuStorage s){store=s;menus=s.load();}void runtime(ZartraGUIPlugin p,ActionExecutor a){plugin=p;actions=a;refresh=new MenuRefreshManager(p,this);}static boolean validId(String id){return id!=null&&id.matches("[a-z0-9_-]{1,32}");}MenuDefinition get(String id){return id==null?null:menus.get(id.toLowerCase());}Collection<MenuDefinition> all(){return menus.values();}MenuDefinition create(String id){MenuDefinition d=new MenuDefinition(id,id,3);menus.put(id,d);return d;}void save(MenuDefinition d)throws IOException{store.save(d);}void saveAll()throws IOException{for(MenuDefinition d:menus.values())store.save(d);}MenuDefinition duplicate(MenuDefinition s,String id){MenuDefinition d=new MenuDefinition(id,s.title,s.rows);d.openingCommand=s.openingCommand;d.openingPermission=s.openingPermission;d.permissionDenied=s.permissionDenied;d.openingSound=s.openingSound;d.closingSound=s.closingSound;d.refreshInterval=s.refreshInterval;d.closeAfterAction=s.closeAfterAction;d.maximumViewers=s.maximumViewers;d.defaultFillerMaterial=s.defaultFillerMaterial;d.paginationContentSlots.addAll(s.paginationContentSlots);for(Map.Entry<Integer,MenuItem> e:s.items.entrySet()){MenuItem o=e.getValue(),n=o.copy();d.items.put(e.getKey(),n);}menus.put(id,d);return d;}boolean delete(String id){menus.remove(id);return store.delete(id);}void shutdown(){if(refresh!=null)refresh.clear();viewers.clear();}void reload(){menus=store.load();viewers.clear();}void opened(Player p,String id){Set<String>s=viewers.get(p.getUniqueId());if(s==null){s=new HashSet<String>();viewers.put(p.getUniqueId(),s);}s.add(id);}void closed(Player p,String id){Set<String>s=viewers.get(p.getUniqueId());if(s!=null){s.remove(id);if(s.isEmpty())viewers.remove(p.getUniqueId());}}int viewers(String id){int n=0;for(Set<String>s:viewers.values())if(s.contains(id))n++;return n;}void clearViewer(Player p){if(refresh!=null)refresh.stop(p);viewers.remove(p.getUniqueId());}
 void open(Player p,MenuDefinition d){open(p,d,1,true);}void open(Player p,MenuDefinition d,int requested){open(p,d,requested,true);}void refreshOpen(Player p,MenuDefinition d,int requested){refreshing.add(p.getUniqueId());try{open(p,d,requested,false);}finally{refreshing.remove(p.getUniqueId());}}boolean refreshing(Player p){return refreshing.contains(p.getUniqueId());}private void open(Player p,MenuDefinition d,int requested,boolean schedule){if(d.openingPermission!=null&&!d.openingPermission.isEmpty()&&!p.hasPermission(d.openingPermission)){p.sendMessage(Chat.c(d.permissionDenied));return;}if(d.maximumViewers>0&&!viewers.containsKey(p.getUniqueId())&&viewers(d.id)>=d.maximumViewers){p.sendMessage(Chat.c("&cThis menu has reached its viewer limit."));return;}if(actions!=null&&!actions.processConditions(p,d,d.openConditions))return;int page=MenuPagination.page(d,requested);String title=plugin==null?Chat.c(d.title):Chat.c(new PlaceholderService(plugin.variables()).replace(p,d,d.title).replace("%page%",String.valueOf(page)).replace("%total_pages%",String.valueOf(MenuPagination.pages(d))));Inventory i=Bukkit.createInventory(new Holder(d.id,false,Screen.NONE,-1,null,-1,page),d.rows*9,title);Map<Integer,MenuItem> shown=MenuPagination.pageItems(d,page);for(Map.Entry<Integer,MenuItem> e:shown.entrySet()){MenuItem item=e.getValue();if(actions!=null&&!actions.conditionsPass(p,d,item.conditions)){if(item.conditions.hideWhenFail)continue;if(item.conditions.replacementMaterial!=null&&!item.conditions.replacementMaterial.isEmpty())i.setItem(e.getKey(),new ItemStack(CompatMaterial.find(item.conditions.replacementMaterial)));continue;}i.setItem(e.getKey(),item.stack());}if(!d.defaultFillerMaterial.isEmpty())for(int n=0;n<i.getSize();n++)if(i.getItem(n)==null)i.setItem(n,new ItemStack(CompatMaterial.find(d.defaultFillerMaterial)));if(!d.paginationContentSlots.isEmpty()){if(page>1)i.setItem(i.getSize()-9,new ItemStack(CompatMaterial.find(d.paginationPreviousMaterial)));if(page<MenuPagination.pages(d))i.setItem(i.getSize()-1,new ItemStack(CompatMaterial.find(d.paginationNextMaterial)));}p.openInventory(i);opened(p,d.id);CompatSound.play(p,d.openingSound);if(actions!=null&&!d.openActions.isEmpty())actions.run(p,d,d.openActions);if(schedule&&refresh!=null)refresh.start(p,d,page);}
 void close(Player p,MenuDefinition d){if(refresh!=null)refresh.stop(p);closed(p,d.id);CompatSound.play(p,d.closingSound);if(actions!=null&&!d.closeActions.isEmpty()&&p.isOnline())actions.run(p,d,d.closeActions);}enum Screen{NONE,MAIN,LIST,ACTIONS,ACTION_LIST,ACTION_EDIT,ACTION_DELETE,CONDITION_LIST,CONDITION_TYPES,CONDITION_EDIT,CONDITION_DELETE,MENU_SETTINGS,ITEM_SETTINGS,LORE_EDITOR,EDITOR_CLOSE}static final class Holder implements InventoryHolder{final String id;final boolean edit;final Screen screen;final int slot,action,sub;final MenuClickType type;Holder(String id,boolean edit,Screen s){this(id,edit,s,-1,null,-1,-1);}Holder(String id,boolean edit,Screen s,int slot){this(id,edit,s,slot,null,-1,-1);}Holder(String id,boolean edit,Screen s,int slot,MenuClickType type,int action){this(id,edit,s,slot,type,action,-1);}Holder(String id,boolean edit,Screen s,int slot,MenuClickType type,int action,int sub){this.id=id;this.edit=edit;screen=s;this.slot=slot;this.type=type;this.action=action;this.sub=sub;}public Inventory getInventory(){return null;}}
}